package br.com.brindespro.admin;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.*;
@Entity @Table(name="kits") public class Kit {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@Column(nullable=false) public String name;public boolean active=true;@Column(name="discount_percent",nullable=false,precision=7,scale=4) public BigDecimal discountPercent=BigDecimal.ZERO;@OneToMany(mappedBy="kit",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) public Set<KitItem> items=new LinkedHashSet<>();protected Kit(){} public Kit(String name){this.name=name;}}
